<?php $sendSnapshot=PurchaseOrderDocument::snapshot($pdo,(int)$selectedPurchaseOrder['id']);$savedOrder=$sendSnapshot['order']; ?>
<?php $emailDraft=(array)($_SESSION['purchase_order_email_drafts'][(int)$savedOrder['id']]??[]);$emailNotice=$_SESSION['purchase_order_email_notice']??null;
if(is_array($emailNotice)&&(int)$emailNotice['order_id']===(int)$savedOrder['id']):unset($_SESSION['purchase_order_email_notice']);?><div class="alert alert-danger mt-3" role="alert"><?=h($emailNotice['message'])?> O texto do email foi conservado.</div><?php endif;?>
<div class="border-top mt-3 pt-3"><a class="btn btn-outline-primary" href="erp.php?page=warehouse&amp;receive_purchase_order=<?=(int)$savedOrder['id']?>#stock-movement">Registar receção parcial no armazém</a>
<details class="mt-3" id="purchase-email-compose" <?=!empty($_GET['compose_email'])||$emailDraft?'open':''?>><summary class="btn btn-primary"><i class="bi bi-send" aria-hidden="true"></i> Enviar ao fornecedor</summary>
<form method="post" onsubmit="this.querySelector('button[type=submit]').disabled=true" action="erp_purchase_document.php" class="row g-2 mt-2"><?=csrf_input()?><input type="hidden" name="dispatch_key" value="<?=h(bin2hex(random_bytes(16)))?>"><input type="hidden" name="purchase_order_id" value="<?=(int)$savedOrder['id']?>"><div class="col-md-6"><label class="form-label">Email do fornecedor</label><input class="form-control" type="email" name="recipient" required value="<?=h((string)($emailDraft['recipient']??$savedOrder['email']))?>"></div><div class="col-md-6"><label class="form-label">Assunto</label><input class="form-control" name="subject" required value="<?=h((string)($emailDraft['subject']??('Encomenda '.$savedOrder['order_number'])))?>"></div><div class="col-12"><label class="form-label">Texto do email</label><textarea class="form-control" name="body" rows="5" required><?=h($emailDraft['body']??("Exmos. Senhores,\n\nSegue em anexo a nossa encomenda ".$savedOrder['order_number'].". Agradecemos a confirmação da receção e da data prevista de entrega.\n\nCom os melhores cumprimentos,\n".$sendSnapshot['company']['name']))?></textarea></div><div class="col-12"><button type="submit" class="btn btn-primary"><i class="bi bi-send"></i> Enviar encomenda com PDF</button><p class="form-text">O envio utiliza os dados guardados. Guarde as alterações antes de enviar.</p></div></form></details>
<div id="purchase-email-history" class="mt-3"><h4 class="h6">Histórico de envios</h4><?php foreach($purchaseHistory as $email):?><div class="border rounded p-2 mb-2"><strong><?=h($email['status'])?></strong> · <?=h($email['created_at'])?> · <?=h($email['recipient'])?><br><?=h($email['subject'])?><details><summary>Mensagem enviada</summary><p><?=nl2br(h($email['body']))?></p></details> <a target="_blank" href="erp_purchase_document.php?archive_id=<?=(int)$email['id']?>">PDF arquivado</a><?php if($email['error_message']):?><p class="text-danger mb-0"><?=h($email['error_message'])?></p><?php endif;?></div><?php endforeach;?><?php if(!$purchaseHistory):?><p class="text-muted">Ainda não foram efetuados envios.</p><?php endif;?></div></div>
<?php $receiptHistory=$pdo->prepare('SELECT sm.movement_number,sm.movement_date,sm.quantity,pol.line_number,u.name operator_name FROM erp_stock_movements sm LEFT JOIN erp_purchase_order_lines pol ON pol.id=sm.purchase_order_line_id LEFT JOIN users u ON u.id=sm.created_by WHERE sm.source_type="purchase_order" AND sm.source_id=? ORDER BY sm.id DESC');$receiptHistory->execute([(int)$savedOrder['id']]);$receipts=$receiptHistory->fetchAll(PDO::FETCH_ASSOC); ?>
<?php if($receipts):?><details class="mt-3"><summary>Histórico de receções (<?=count($receipts)?>)</summary><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Movimento</th><th>Data</th><th>Linha</th><th>Quantidade recebida</th><th>Utilizador</th></tr></thead><tbody><?php foreach($receipts as $receipt):?><tr><td><?=h($receipt['movement_number'])?></td><td><?=h($receipt['movement_date'])?></td><td><?=h($receipt['line_number'])?></td><td><?=h($receipt['quantity'])?></td><td><?=h($receipt['operator_name'])?></td></tr><?php endforeach;?></tbody></table></div></details><?php endif;?>
